const out = 'test-results/gap-syntax-20261019';
fs.mkdirSync(out, { recursive: true });
const corpusPath = 'syntax_corpus/oracle/vbe_oracle_cases.json';
const corpus = JSON.parse(fs.readFileSync(corpusPath, 'utf8'));
const fixtures = corpus.cases.filter(c => c.id.startsWith('rq17_') || c.id.startsWith('gap_syntax_20261019_'));
if (fixtures.length !== 50 || fixtures.some(c => c.mode !== 'compile' || c.host !== 'excel')) throw new Error('Unexpected fixture selection');
const controls = ['missing_trailing_required_argument', 'bare_variable_statement', 'number_to_string_assignment'];
const hashes = {};
for (const file of [corpusPath, 'syntax_corpus/oracle/run_vbe_oracle.mjs', 'syntax_corpus/oracle/vbe_oracle_worker.ps1', 'src/officeHostApps.ts', 'gap-syntax-windows-validation.cjs']) hashes[file] = crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
const environmentScript = `$ErrorActionPreference='Stop'; $k=Get-ItemProperty 'HKLM:\\SOFTWARE\\Microsoft\\Office\\ClickToRun\\Configuration'; $cls=[type]::GetTypeFromProgID('Excel.Application'); $id=$cls.GUID.ToString('B'); $server=(Get-Item ('Registry::HKEY_CLASSES_ROOT\\CLSID\\'+$id+'\\LocalServer32')).GetValue(''); $exe=if($server -match '^"([^\"]+)"'){ $Matches[1] }else{ $server -replace '\\s+/.*$','' }; [ordered]@{timestampUtc=[DateTime]::UtcNow.ToString('o');machine=$env:COMPUTERNAME;os=[Environment]::OSVersion.VersionString;officeProduct=$k.ProductReleaseIds;officePlatform=$k.Platform;officeVersion=$k.VersionToReport;excelExecutable=$exe;excelFileVersion=(Get-Item $exe).VersionInfo.FileVersion;officeProcesses=@(Get-Process EXCEL,WINWORD,POWERPNT,MSACCESS -ErrorAction SilentlyContinue | Select-Object ProcessName,Id,StartTime)} | ConvertTo-Json -Depth 5`;
