fs.writeFileSync(path.join(out, 'environment.stderr.txt'), envRun.stderr || '');
if (envRun.status !== 0) throw new Error('Environment capture failed: '+envRun.stderr);
const environment = JSON.parse(envRun.stdout.replace(/^\uFEFF/, ''));
fs.writeFileSync(path.join(out, 'environment.json'), JSON.stringify({ ...environment, node: process.version, platform: process.platform, architecture: process.arch, hashes, selectedFixtureIds: fixtures.map(c => c.id) }, null, 2)+'\n');
function run(name, ids, selected) {
